 11→/// Built-in secret patterns that are always masked.
 12→///
 13→/// These patterns use simple glob-style matching where `*` matches
 14→/// any characters.
 15→pub const SECRET_PATTERNS: &[&str] = &[
 16→    "*_KEY",
 17→    "*_SECRET",
 18→    "*_TOKEN",
 19→    "*_PASSWORD",
 20→    "*_CREDENTIAL",
 21→    "API_KEY",
 22→    "SECRET_KEY",
 23→    "ACCESS_TOKEN",
 24→    "AUTH_TOKEN",
 25→    "DATABASE_URL",
 26→    "REDIS_URL",
 27→    "AWS_*",
 28→    "GITHUB_TOKEN",
 29→    "OPENAI_API_KEY",
