  1→//! Configuration loading, parsing, and validation for Bivvy.
  2→//!
  3→//! This module handles all aspects of configuration:
  4→//! - Schema definitions in [`schema`]
  5→//! - File discovery and loading in [`loader`]
  6→//! - Deep merging in [`merger`]
  7→//! - Validation in [`validator`]
  8→//! - Variable interpolation in [`interpolation`]
  9→//! - Environment variable handling in [`environment`]
 10→//!
 11→//! # Example
 12→//!
 13→//! ```
 14→//! use bivvy::config::{load_merged_config, validate};
 15→//! use tempfile::TempDir;
 16→//! use std::fs;
 17→//!
 18→//! let temp = TempDir::new().unwrap();
 19→//! let bivvy_dir = temp.path().join(".bivvy");
 20→//! fs::create_dir_all(&bivvy_dir).unwrap();
 21→//! fs::write(bivvy_dir.join("config.yml"), "app_name: test").unwrap();
 22→//!
 23→//! let config = load_merged_config(temp.path()).unwrap();
 24→//! validate(&config).unwrap();
 25→//! assert_eq!(config.app_name, Some("test".to_string()));
 26→//! ```
 27→//!
 28→//! # Configuration File Locations
 29→//!
 30→//! Bivvy discovers and merges configuration in this order:
 31→//! 1. Remote base configs (from `extends:`)
 32→//! 2. User global config (`~/.bivvy/config.yml`)
 33→//! 3. Project config (`.bivvy/config.yml`)
 34→//! 4. Local overrides (`.bivvy/config.local.yml`)
 35→
 36→pub mod env_file;
 37→pub mod env_layer;
 38→pub mod environment;
 39→pub mod extends;
 40→pub mod interpolation;
 41→pub mod loader;
 42→pub mod merger;
 43→pub mod remote;
 44→pub mod schema;
 45→pub mod validator;
 46→pub mod vars;
 47→
 48→// Schema re-exports
 49→pub use schema::{
 50→    BivvyConfig, CompletedCheck, CustomRequirement, CustomRequirementCheck, OutputMode,
 51→    PromptConfig, PromptType, SecretConfig, Settings, StepConfig, StepEnvironmentOverride,
 52→    StepOutputConfig, StepOverride, TemplateSource, VarDefinition, WorkflowConfig,
 53→    WorkflowSettings,
 54→};
 55→
 56→// Vars re-exports
 57→pub use vars::evaluate_vars;
 58→
 59→// Loader re-exports
 60→pub use loader::{
 61→    find_project_root, load_config, load_config_file, load_config_value, load_merged_config,
 62→    load_merged_config_with_resolver, parse_config, ConfigPaths,
 63→};
 64→
 65→// Merger re-exports
 66→pub use merger::{deep_merge, merge_configs};
 67→
 68→// Validator re-exports
 69→pub use validator::{validate, validate_config, ValidationError};
 70→
 71→// Interpolation re-exports
 72→pub use interpolation::{
 73→    extract_variables, has_interpolation, parse_interpolation, resolve_string,
 74→    resolve_string_with_default, InterpolationContext, Segment,
 75→};
 76→
