        }
    })?;

    match detect_format(path) {
        ConfigFormat::Toml => {
            let toml_value: toml::Value =
                toml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                    path: path.to_path_buf(),
                    message: e.to_string(),
                })?;
            serde_yaml::to_value(toml_value).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: format!("Failed to convert TOML to merge format: {e}"),
            })
        }
        ConfigFormat::Yaml => {
            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })
        }
    }
}

